import { useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/Button.js';
import { t } from '@/i18n/index.js';
import { ReportSheet } from './ReportSheet.js';
import { decodeHandoff } from './report.js';
import styles from './Report.module.css';

/**
 * `/report-ai#r=…`: where the Report link on the desktop app's card and the
 * browser extension's card lands. Those cards cannot draw the sheet, so they
 * hand the text over in the link's fragment and the sheet opens here, as
 * the learner who tapped Report. A link with nothing readable in it says so.
 */
export function ReportAi(): React.JSX.Element {
  const location = useLocation();
  const navigate = useNavigate();
  const target = useMemo(() => decodeHandoff(location.hash), [location.hash]);
  const leave = (): void => {
    void navigate('/', { replace: true });
  };

  return (
    <main className={styles.page}>
      <h1 className={styles.pageTitle}>{t('report.pageTitle')}</h1>
      {target === undefined ? (
        <>
          <p className={styles.pageNote}>{t('report.pageEmpty')}</p>
          <Button variant="secondary" onClick={leave}>
            {t('report.pageBack')}
          </Button>
        </>
      ) : (
        <ReportSheet target={target} onClose={leave} />
      )}
    </main>
  );
}
